// Hand-written. Not generated by Speakeasy.
//
// Machinery for migrating state written by the hand-written v1.3.x provider.
//
// v1.3.17 was built on terraform-plugin-sdk v2 and declared no SchemaVersion,
// so Terraform recorded its state as version 0. This provider declared no
// version either until x-speakeasy-entity-version was added, so Terraform saw
// 0 against 0, ran no upgrade, and emitted no warning. It loaded the old state
// into the new schema, dropped what it could not match, and left the renamed
// identifiers null -- producing requests to /api/0/service/get (403 A458203)
// and /api//client/get/<id> (400) on the first refresh after upgrading.
//
// Only the identifiers need carrying across. Every other attribute is either
// supplied by configuration or returned by the API on the next read, so an
// attribute that does not survive the migration is repopulated rather than
// lost. The identifiers are the exception precisely because they are the
// lookup key: without them nothing can be read back at all.
//
// Speakeasy registers these upgraders without a PriorSchema, so the framework
// hands over raw JSON and validates whatever we return against the *current*
// schema, strictly, failing on the first attribute it does not recognise. An
// old service state carries on the order of a hundred such attributes, so
// stripping them individually would never converge. Instead we rename the
// identifiers on the raw map and re-decode with IgnoreUndefinedAttributes,
// which drops everything unrecognised at any depth in one pass.
package stateupgraders

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"sync"

	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-go/tfprotov6"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// The current schema types, injected by the provider package. They cannot be
// imported directly: the provider package imports this one, so the dependency
// has to run the other way at runtime.
var (
	schemaMu    sync.RWMutex
	schemaTypes = map[string]tftypes.Type{}
)

// RegisterSchemaType is called from the provider package during init.
func RegisterSchemaType(entity string, t tftypes.Type) {
	schemaMu.Lock()
	defer schemaMu.Unlock()
	schemaTypes[entity] = t
}

func schemaTypeFor(entity string) (tftypes.Type, bool) {
	schemaMu.RLock()
	defer schemaMu.RUnlock()
	t, ok := schemaTypes[entity]
	return t, ok
}

// rename moves one attribute from its v1.3.x name to its current one.
type rename struct {
	from string
	to   string
	// toNumber converts a JSON string to a JSON number. v1.3.x stored both
	// identifiers as SDKv2's implicit `id`, which is always a string; the
	// current schema types them as Int64.
	toNumber bool
	// mustBeSet marks an identifier that cannot be recovered any other way.
	// When it is absent or empty the migration stops with remediation rather
	// than producing state that fails on the next refresh.
	mustBeSet   bool
	ifNotSetSay string
}

func upgrade(_ context.Context, entity string, renames []rename, req resource.UpgradeStateRequest, resp *resource.UpgradeStateResponse) {
	schemaType, ok := schemaTypeFor(entity)
	if !ok {
		resp.Diagnostics.AddError(
			"State upgrade is not wired up",
			fmt.Sprintf("No current schema registered for %q. This is a provider bug: "+
				"internal/provider/stateupgrade_schema.go should register it during init.", entity),
		)
		return
	}

	if req.RawState == nil || len(req.RawState.JSON) == 0 {
		resp.Diagnostics.AddError(
			"Cannot upgrade state",
			"The prior state carried no JSON payload, so there is nothing to migrate.",
		)
		return
	}

	var attrs map[string]json.RawMessage
	if err := json.Unmarshal(req.RawState.JSON, &attrs); err != nil {
		resp.Diagnostics.AddError("Cannot read prior state", err.Error())
		return
	}

	for _, r := range renames {
		// State already carrying the current name needs no rename. Terraform
		// recorded every v3-draft build before x-speakeasy-entity-version was
		// added as version 0, the same version v1.3.x wrote, so this upgrader
		// runs over state that is already in the current shape. Without this
		// check those resources stopped with "api_key is missing" -- naming an
		// attribute that is in fact present and correct.
		if to, ok := attrs[r.to]; ok {
			if _, blank := stringish(to); !blank {
				delete(attrs, r.from)
				continue
			}
		}

		raw, present := attrs[r.from]
		value, empty := stringish(raw)

		if !present || empty {
			if r.mustBeSet {
				resp.Diagnostics.AddError(
					fmt.Sprintf("Cannot migrate this resource automatically: %s is missing", r.to),
					r.ifNotSetSay,
				)
				return
			}
			continue
		}

		if r.toNumber {
			if !numeric(value) {
				resp.Diagnostics.AddError(
					fmt.Sprintf("Cannot migrate %s", r.to),
					fmt.Sprintf("Expected %q to hold a numeric identifier, got %q.", r.from, value),
				)
				return
			}
			attrs[r.to] = json.RawMessage(value)
		} else {
			attrs[r.to] = raw
		}
		delete(attrs, r.from)
	}

	migrated, err := json.Marshal(attrs)
	if err != nil {
		resp.Diagnostics.AddError("Cannot rewrite prior state", err.Error())
		return
	}

	// Everything this provider no longer defines is dropped here rather than
	// enumerated. See the package comment for why.
	raw := tfprotov6.RawState{JSON: migrated}
	value, err := raw.UnmarshalWithOpts(schemaType, tfprotov6.UnmarshalOpts{
		ValueFromJSONOpts: tftypes.ValueFromJSONOpts{IgnoreUndefinedAttributes: true},
	})
	if err != nil {
		resp.Diagnostics.AddError("Cannot decode migrated state", err.Error())
		return
	}

	dynamic, err := tfprotov6.NewDynamicValue(schemaType, value)
	if err != nil {
		resp.Diagnostics.AddError("Cannot encode migrated state", err.Error())
		return
	}
	resp.DynamicValue = &dynamic
}

// stringish unwraps a JSON string, reporting whether the result is empty. A
// non-string is returned verbatim and treated as non-empty.
func stringish(raw json.RawMessage) (string, bool) {
	if len(raw) == 0 {
		return "", true
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return strings.TrimSpace(string(raw)), false
	}
	return s, strings.TrimSpace(s) == ""
}

func numeric(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}
